--- a//home/xyconix11x/Ayid/xyconix11x/Skripsi/Daedalus/jojo/style.css
+++ b//home/xyconix11x/Ayid/xyconix11x/Skripsi/Daedalus/jojo/style.css
@@ +62 -0 @@
+@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&display=swap');
+
+:root {
+  --navy: #102a43;
+  --blue: #1677ff;
+  --sky: #eaf4ff;
+  --ink: #172b4d;
+  --muted: #62748a;
+  --line: #dce7f2;
+  --white: #fff;
+  --shadow: 0 18px 45px rgba(16, 42, 67, .12);
+}
+
+* { box-sizing: border-box; }
+html { scroll-behavior: smooth; }
+body { margin: 0; color: var(--ink); background: #f8fbff; font: 16px/1.7 'DM Sans', sans-serif; }
+.container { width: min(1120px, calc(100% - 40px)); margin: auto; }
+.top-bar { position: sticky; top: 0; z-index: 10; background: rgba(255,255,255,.92); border-bottom: 1px solid var(--line); backdrop-filter: blur(12px); }
+.top-bar .container { min-height: 74px; display: flex; align-items: center; justify-content: space-between; gap: 24px; }
+.logo { color: var(--navy); font-size: 1.35rem; font-weight: 700; letter-spacing: -.04em; }
+.top-nav { display: flex; flex-wrap: wrap; gap: 26px; }
+a { color: inherit; text-decoration: none; }
+.top-nav a { color: var(--muted); font-size: .92rem; font-weight: 600; transition: color .2s; }
+.top-nav a:hover, .top-nav a:focus-visible { color: var(--blue); }
+.hero { padding: 120px 0 135px; color: var(--white); background: radial-gradient(circle at 85% 20%, #43a8ff 0, transparent 30%), linear-gradient(125deg, #102a43, #1261a0); }
+.hero h1 { max-width: 700px; margin: 0 0 18px; font: 700 clamp(2.5rem, 6vw, 4.7rem)/1.08 'Playfair Display', serif; letter-spacing: -.04em; }
+.hero p { max-width: 570px; margin: 0 0 32px; color: #dceeff; font-size: 1.15rem; }
+.cta-btn, button { display: inline-block; border: 0; border-radius: 9px; padding: 13px 22px; color: var(--white); background: var(--blue); font: 600 1rem 'DM Sans', sans-serif; cursor: pointer; transition: transform .2s, box-shadow .2s, background .2s; }
+.cta-btn:hover, button:hover { background: #075dcc; box-shadow: 0 10px 20px rgba(22,119,255,.25); transform: translateY(-2px); }
+section { padding: 88px 0; }
+h2 { margin: 0 0 12px; color: var(--navy); font: 700 clamp(2rem, 4vw, 3rem)/1.2 'Playfair Display', serif; }
+.about { background: var(--white); }
+.about-grid, .contact-grid { display: grid; grid-template-columns: 1fr 1fr; align-items: center; gap: 58px; margin-top: 34px; }
+.about-grid p { color: var(--muted); }
+.about-img { width: 100%; border-radius: 18px; box-shadow: var(--shadow); }
+.catalog { background: var(--sky); }
+.subtitle { margin: 0 0 30px; color: var(--muted); }
+.product-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 22px; }
+.product-card { overflow: hidden; border: 1px solid var(--line); border-radius: 16px; background: var(--white); box-shadow: 0 8px 24px rgba(16,42,67,.06); transition: transform .2s, box-shadow .2s; }
+.product-card:hover { transform: translateY(-5px); box-shadow: var(--shadow); }
+.product-card img { display: block; width: 100%; height: 180px; object-fit: cover; }
+.product-card > div { padding: 20px; }
+.product-card h3 { margin: 0 0 7px; color: var(--navy); }
+.product-card p { margin: 0; color: var(--muted); }
+.contact-form { display: grid; gap: 13px; }
+input, textarea { width: 100%; border: 1px solid var(--line); border-radius: 8px; padding: 14px 15px; color: var(--ink); background: var(--white); font: inherit; resize: vertical; }
+input:focus, textarea:focus { outline: 3px solid rgba(22,119,255,.2); border-color: var(--blue); }
+.contact-info { padding: 28px; border-radius: 16px; color: var(--muted); background: var(--sky); }
+.contact-info p { margin: 0 0 18px; }
+.contact-info strong { color: var(--navy); }
+.form-status { margin-top: 16px; color: var(--blue); font-weight: 600; }
+.footer { padding: 25px 0; color: #bcd2e5; background: var(--navy); text-align: center; }
+.footer p { margin: 0; font-size: .9rem; }
+@media (max-width: 760px) {
+  .top-bar .container { align-items: flex-start; flex-direction: column; padding: 16px 0; }
+  .top-nav { gap: 12px 18px; }
+  .hero { padding: 82px 0 95px; }
+  section { padding: 62px 0; }
+  .about-grid, .contact-grid, .product-grid { grid-template-columns: 1fr; gap: 25px; }
+  .about-grid { margin-top: 22px; }
+}
+@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; transition: none !important; } }
